        var isCurrent = step == CurrentStep;
        var isFuture = step > CurrentStep;

        <button class="btn btn-sm rounded-pill @StepClass(step)"
                disabled="@(isFuture || Submitted)"
                @onclick="() => GoToStep(step)">
            @if (isCompleted)
            {
                <span>&#10003; </span>
            }
            <span>@step. @label</span>
        </button>

        if (step < StepLabels.Length)
        {
            <span class="text-muted mx-1">&rarr;</span>
        }
    }
</nav>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

@* ───── Step 1: Personal Info ───── *@
@if (CurrentStep == 1)
{
    <div class="card p-4">
        <h4>Personal Information</h4>
        <div class="mb-3">
            <label class="form-label">Full Name <span class="text-danger">*</span></label>
            <input class="form-control" @bind="FullName" />
        </div>
        <div class="mb-3">
            <label class="form-label">Email <span class="text-danger">*</span></label>
            <input type="email" class="form-control" @bind="Email" />
        </div>
        <div class="mb-3">
            <label class="form-label">Phone <span class="text-danger">*</span></label>
            <input type="tel" class="form-control" @bind="Phone" />
        </div>
        <div class="mb-3">
            <label class="form-label">Address <span class="text-danger">*</span></label>
            <textarea class="form-control" rows="2" @bind="Address"></textarea>
        </div>
        <div class="d-flex justify-content-end">
            <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@IsLoading">
                @if (IsLoading) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Next
            </button>
        </div>
    </div>
}

@* ───── Step 2: Work History ───── *@
@if (CurrentStep == 2)
{
    <div class="card p-4">
        <h4>Work History</h4>
        @for (int idx = 0; idx < WorkEntries.Count; idx++)
        {
            var i = idx;
            var entry = WorkEntries[i];
            <div class="border rounded p-3 mb-3">
                <div class="d-flex justify-content-between align-items-center mb-2">
                    <h6 class="mb-0">Position @(i + 1)</h6>
                    @if (WorkEntries.Count > 1)
                    {
                        <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(i)">Remove</button>
                    }
                </div>
                <div class="row mb-2">
                    <div class="col-md-6">
                        <label class="form-label">Company <span class="text-danger">*</span></label>
                        <input class="form-control" @bind="entry.Company" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Job Title <span class="text-danger">*</span></label>
                        <input class="form-control" @bind="entry.Title" />
                    </div>
                </div>
                <div class="row mb-2">
