        </div>
    </div>
}

@* ───── Step 4: Cover Letter ───── *@
@if (CurrentStep == 4)
{
    <div class="card p-4">
        <h4>Cover Letter</h4>
        <div class="mb-2">
            <textarea class="form-control" rows="10" maxlength="2000"
