            <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@IsLoading">
                @if (IsLoading) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Submit Application
            </button>
        </div>
    </div>
}

