}

@code {
    private static readonly string[] StepLabels =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    private int CurrentStep { get; set; } = 1;
    private bool IsLoading { get; set; }
    private bool Submitted { get; set; }
    private int? ApplicationId { get; set; }
    private string? ErrorMessage { get; set; }

    // Step 1
    private string FullName { get; set; } = "";
    private string Email { get; set; } = "";
    private string Phone { get; set; } = "";
    private string Address { get; set; } = "";

    // Step 2
    private List<WorkEntryModel> WorkEntries { get; set; } = [new()];

    // Step 3
    private List<ReferenceModel> References { get; set; } = [new(), new()];

    // Step 4
    private string CoverLetter { get; set; } = "";

    // ── Helpers ──

    private string StepClass(int step) =>
        step == CurrentStep ? "btn-primary" :
        step < CurrentStep ? "btn-outline-success" :
        "btn-outline-secondary opacity-50";

    private void GoToStep(int step)
    {
        if (step <= CurrentStep && !Submitted)
        {
            ErrorMessage = null;
            CurrentStep = step;
        }
    }

    // ── Step 1 Navigation ──

    private async Task NextFromPersonalInfo()
    {
        ErrorMessage = null;
        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email)
            || string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "Please fill in all required fields.";
            return;
        }

        IsLoading = true;
        try
        {
            var valid = await ApplicationService.ValidateEmailAsync(Email);
            if (!valid)
            {
                ErrorMessage = "Please enter a valid email address.";
                return;
            }
            CurrentStep = 2;
        }
        finally
        {
            IsLoading = false;
        }
    }

    // ── Step 2 Navigation ──

    private void AddWorkEntry() => WorkEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (WorkEntries.Count > 1)
            WorkEntries.RemoveAt(index);
    }

    private void NextFromWorkHistory()
    {
        ErrorMessage = null;
        foreach (var e in WorkEntries)
        {
            if (string.IsNullOrWhiteSpace(e.Company) || string.IsNullOrWhiteSpace(e.Title)
                || e.StartDate == default)
            {
                ErrorMessage = "Please fill in company, title, and start date for every position.";
                return;
            }
        }
        CurrentStep = 3;
    }

    // ── Step 3 Navigation ──

    private void AddReference()
    {
        if (References.Count < 3) References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2) References.RemoveAt(index);
    }

    private void NextFromReferences()
    {
        ErrorMessage = null;
        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                ErrorMessage = "Please fill in all fields for every reference.";
                return;
            }
        }
        CurrentStep = 4;
    }

    // ── Submit ──

    private async Task SubmitApplication()
    {
        IsLoading = true;
        ErrorMessage = null;
        try
        {
            var personal = new PersonalInfo(FullName, Email, Phone, Address);
            var work = new WorkHistory(WorkEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
            var refs = References.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var application = new JobApplication(personal, work, refs, CoverLetter);

            ApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            Submitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsLoading = false;
        }
    }

    // ── Mutable view‑models for form binding ──

    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

